package io.tuji.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.SystemClock;import android.view.*;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import static org.junit.Assert.*;
public class PaintSelectionTest {
 @Test public void longPressPaintsOnlyCrossedCellsAndRollsBack()throws Exception{Instrumentation i=InstrumentationRegistry.getInstrumentation();MainActivity a=(MainActivity)i.startActivitySync(new Intent(i.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1200);i.runOnMainSync(()->{a.selected.clear();a.galleryScreen.columns=6;a.galleryScreen.rebuild();});Thread.sleep(300);float[] xy=new float[6];
 i.runOnMainSync(()->{GalleryScreen g=a.galleryScreen;GalleryScreen.Holder h=null;for(int n=0;n<g.list.getChildCount();n++)if(g.list.getChildAt(n).getTag() instanceof GalleryScreen.Holder){h=(GalleryScreen.Holder)g.list.getChildAt(n).getTag();break;}assertNotNull(h);for(int n=0;n<3;n++){Rect r=new Rect();h.cells[n].getDrawingRect(r);g.offsetDescendantRectToMyCoords(h.cells[n],r);xy[n*2]=r.centerX();xy[n*2+1]=r.centerY();}event(g,0,xy[0],xy[1]);});Thread.sleep(ViewConfiguration.getLongPressTimeout()+200);
 i.runOnMainSync(()->{GalleryScreen g=a.galleryScreen;assertTrue("actual long press starts paint",g.painting);event(g,2,xy[4],xy[5]);assertEquals("fast line crosses exactly three cells",3,a.selected.size());event(g,2,xy[0],xy[1]);assertEquals("backtracking shrinks current range",1,a.selected.size());event(g,3,xy[0],xy[1]);assertTrue("cancel restores baseline",a.selected.isEmpty());assertFalse(g.painting);a.selected.add(android.net.Uri.parse(g.filtered.get(0).uri));g.beginPaint(g.filtered.get(5));g.paintAdd(g.filtered.get(15));assertEquals("entire range plus baseline",12,a.selected.size());g.paintAdd(g.filtered.get(8));assertEquals("shrink preserves baseline",5,a.selected.size());g.paintAdd(g.filtered.get(2));assertEquals("cross anchor",5,a.selected.size());g.endPaint(false);assertEquals("rollback preserves baseline",1,a.selected.size());a.selected.clear();assertEquals(a.dp(24),g.rail.getWidth());});i.runOnMainSync(a::finish);}
 static void event(GalleryScreen g,int action,float x,float y){long t=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(t,t,action,x,y,0);g.dispatchTouchEvent(e);e.recycle();}
}
